import{_ as e,o as i,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"Android Native Bank APK","description":"","frontmatter":{"title":"Android Native Bank APK"},"headers":[],"relativePath":"operations/android-native-bank-apk.md","filePath":"operations/android-native-bank-apk.md","lastUpdated":1787839527000}'),o={name:"operations/android-native-bank-apk.md"};function s(r,a,d,l,p,h){return i(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="android-原生銀行-apk" tabindex="-1">Android 原生銀行 APK <a class="header-anchor" href="#android-原生銀行-apk" aria-label="Permalink to &quot;Android 原生銀行 APK&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>第一銀行／華南同步跑在 <strong>Android WebView 原生碼</strong>（<code>FirstBankAutomation.java</code>、<code>HuaNanBankAutomation.java</code>）。<br><strong>只有重建 APK 才會到手機。</strong> <code>deploy:copy</code>、version bump、web 測試、Playwright <strong>都不會</strong> ship 原生修復。</p><h2 id="生產路徑" tabindex="-1">生產路徑 <a class="header-anchor" href="#生產路徑" aria-label="Permalink to &quot;生產路徑&quot;">​</a></h2><ul><li>僅 Android native。Web 遠端 scrape 已退役。</li><li>雙 flag：<code>VITE_BANK_SYNC_FEATURE_ENABLED</code> <strong>且</strong> <code>VITE_BANK_SYNC_ENABLE_UNSUPPORTED_REAL_PROVIDERS</code>（見 <a href="/operations/environment-variables.html">Environment-Variables</a>）。</li><li>入口：功能頁「進階功能」，不是設定主清單。</li></ul><h2 id="重建" tabindex="-1">重建 <a class="header-anchor" href="#重建" aria-label="Permalink to &quot;重建&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/data/code/project/StrawCoding/StrawMoneyBook/frontend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ANDROID_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/android-sdk</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># APK: frontend/android/app/build/outputs/apk/release/app-release.apk</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># versionName: output-metadata.json</span></span></code></pre></div><p>Play AAB／上架走 <a href="/operations/android-release-and-play-upload.html">Android-Release-And-Play-Upload</a>，和「側載 APK 驗原生銀行」是兩條路。</p><h2 id="phase-0c-真機閘-第一銀行" tabindex="-1">Phase 0C 真機閘（第一銀行） <a class="header-anchor" href="#phase-0c-真機閘-第一銀行" aria-label="Permalink to &quot;Phase 0C 真機閘（第一銀行）&quot;">​</a></h2><p>程式已有 watermark + 強制 lookback。真機必須證明：</p><ol><li>安裝<strong>剛重建</strong>的 APK（versionName 對得上本次 commit）。</li><li>第一次同步拉初始窗。</li><li>第二次同步查詢窗 = <code>coveredThrough - lookbackDays</code>（預設 3 日），<strong>不是</strong>整段重拉。</li></ol><p>未做這步，不得宣稱「增量同步已在使用者裝置上可用」。步驟與剩餘階段：<a href="/operations/sync-architecture-b.html">Sync-Architecture-B</a>。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/android" target="_blank" rel="noreferrer"><code>frontend/android/app/src/main/java/.../FirstBankAutomation.java</code></a></li><li><a href="/operations/sync-operations-runbooks.html">Sync-Operations-Runbooks</a></li></ul>`,14)])])}const u=e(o,[["render",s]]);export{k as __pageData,u as default};
